<script setup lang="ts">
import { computed, nextTick, reactive, ref, watch } from 'vue'
import { PhCpu, PhFolderOpen, PhMagnifyingGlass, PhPlay, PhCheckCircle, PhWarningCircle, PhArrowClockwise, PhExport, PhFilmStrip, PhX, PhTerminalWindow, PhActivity, PhInfo, PhSlidersHorizontal, PhArrowSquareOut, PhTrash } from '@phosphor-icons/vue'
import type { Snapshot, OutputFile, TaskRecord, Settings, TaskStatus } from '../../shared/contracts'
import { canRemoveTask } from '../../shared/task-policy'
import ModelRecommendations from './ModelRecommendations.vue'
import WorkflowLibrary from './WorkflowLibrary.vue'
import BootstrapSetup from './BootstrapSetup.vue'
import UiPreferencesControl from './UiPreferencesControl.vue'
import type { UiPreferences } from '../src/ui-preferences'
import { desktop, invoke } from '../src/api'

const props = defineProps<{ page: string; snapshot: Snapshot; busy: boolean; mediaUrl: (output: OutputFile) => string; uiPreferences?: UiPreferences }>()
const emit = defineEmits<{ action: [command: string, payload?: unknown]; create: [mode?: 'image' | 'text']; restore: [task: TaskRecord]; uiPreferences: [value: UiPreferences] }>()
const draft = reactive<Settings>({ ...props.snapshot.settings })
watch(() => JSON.stringify(props.snapshot.settings), () => Object.assign(draft, props.snapshot.settings))
const pathFields = [
  { key: 'installationPath', label: '运行环境', hint: '包含 ComfyUI 和独立 Python 的安装根目录' },
  { key: 'modelPath', label: '模型目录', hint: '复用已有权重，避免重复下载' },
  { key: 'outputPath', label: '作品输出', hint: '生成作品的保存位置' },
  { key: 'inputPath', label: '输入素材', hint: 'ComfyUI 的输入图片目录' },
] as const
const pathError = ref('')
function save() {
  const values = pathFields.map(f => draft[f.key].trim())
  if (values.some(v => !v)) { pathError.value = '请填写所有本地目录。'; return }
  try {
    const u = new URL(draft.engineUrl)
    if (u.protocol !== 'http:' || !['127.0.0.1', 'localhost', '[::1]'].includes(u.hostname) || u.username || u.password || (u.pathname !== '/' && u.pathname !== '') || u.search || u.hash) throw new Error()
  } catch { pathError.value = '服务地址需使用本机 HTTP 地址，例如 http://127.0.0.1:8188。'; return }
  pathError.value = ''
  emit('action', 'settings.save', { ...draft, initialized: true })
}
const gpu = computed(() => props.snapshot.hardware.gpuName || '尚未识别显卡')
const vram = computed(() => props.snapshot.hardware.vramMb > 0 ? `${(props.snapshot.hardware.vramMb / 1024).toFixed(1)} GB 显存` : '显存待检测')
const engineReady = computed(() => ['ready', 'busy'].includes(props.snapshot.engine.status))
const query = ref('')
const templates = computed(() => props.snapshot.templates.filter(t => `${t.name} ${t.description}`.toLowerCase().includes(query.value.toLowerCase())))
const templateCards = computed(() => templates.value.flatMap(template => (['image', 'text'] as const).map(mode => ({ template, mode }))))
const showDependencies = ref(false)
function dependencies() { showDependencies.value = true; emit('action', 'template.validate') }
const taskTab = ref('tasks')
const statusFilter = ref('all')
const selectedId = ref('')
const removingId = ref('')
const deleteButton = ref<HTMLButtonElement | null>(null)
const keepButton = ref<HTMLButtonElement | null>(null)
async function requestRemove(task: TaskRecord) {
  if (props.busy || !removable(task)) return
  removingId.value = task.id
  await nextTick(); keepButton.value?.focus({ preventScroll: true })
}
async function keepHistory() {
  removingId.value = ''
  await nextTick(); deleteButton.value?.focus({ preventScroll: true })
}
const statusNames: Record<TaskStatus, string> = { submitting: '提交中', queued: '排队中', running: '生成中', completed: '已完成', failed: '失败', interrupted: '已中断', unknown: '状态待确认' }
const pageIndex = ref(1)
const pageSize = 20
const allVisibleTasks = computed(() => props.snapshot.tasks.filter(t => (taskTab.value !== 'works' || t.status === 'completed') && (statusFilter.value === 'all' || t.status === statusFilter.value) && `${t.title} ${t.params.prompt}`.toLowerCase().includes(query.value.toLowerCase())).slice().sort((a, b) => b.createdAt.localeCompare(a.createdAt)))
const pageCount = computed(() => Math.max(1, Math.ceil(allVisibleTasks.value.length / pageSize)))
const visibleTasks = computed(() => allVisibleTasks.value.slice((pageIndex.value - 1) * pageSize, pageIndex.value * pageSize))
watch([taskTab, statusFilter, query], () => { pageIndex.value = 1 })
watch(pageCount, count => { pageIndex.value = Math.min(pageIndex.value, count) })
const selectedTask = computed(() => visibleTasks.value.find(t => t.id === selectedId.value) || visibleTasks.value[0])
const currentTask = computed(() => props.snapshot.tasks.find(t => ['submitting', 'running', 'queued'].includes(t.status)))
const cancellable = (t: TaskRecord) => ['submitting', 'queued', 'running'].includes(t.status)
const retryable = (t: TaskRecord) => ['failed', 'interrupted'].includes(t.status)
const removable = (t: TaskRecord) => canRemoveTask(t.status)
watch(() => selectedTask.value?.id, () => { removingId.value = '' })
function removeHistory(task: TaskRecord) {
  if (props.busy || !removable(task) || removingId.value !== task.id) return
  removingId.value = ''
  emit('action', 'task.remove', { id: task.id })
}
const percent = (t: TaskRecord) => t.progress && t.progress.max > 0 ? Math.min(100, Math.max(0, Math.round(t.progress.value / t.progress.max * 100))) : 0
const date = (value: string) => new Date(value).toLocaleString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false })
const resourceTab = ref('model')
const resourceMode = ref('recommendations')
const resources = computed(() => props.snapshot.resources.filter(r => r.kind === resourceTab.value))
const installed = computed(() => props.snapshot.resources.filter(r => r.status === 'installed').length)
const resourceSize = computed(() => props.snapshot.resources.reduce((sum, r) => sum + (r.status === 'installed' ? r.sizeBytes : 0), 0))
const size = (bytes: number) => bytes > 0 ? `${(bytes / 1024 ** 3).toFixed(2)} GiB` : '—'
const settingsTab = ref('general')
type CloseBehavior = 'ask' | 'background' | 'quit'
const closeBehavior = ref<CloseBehavior>('ask')
const closePreferenceReady = ref(false)
const closePreferenceBusy = ref(false)
const closePreferenceFeedback = ref('')
const closePreferenceError = ref('')
async function loadClosePreference() {
  if (!desktop || closePreferenceBusy.value) return
  closePreferenceBusy.value = true; closePreferenceError.value = ''
  try {
    const value = await invoke<{ behavior: CloseBehavior }>('native.closePreferences.get')
    if (!['ask', 'background', 'quit'].includes(value.behavior)) throw new Error('关闭方式暂时无法读取。')
    closeBehavior.value = value.behavior; closePreferenceReady.value = true
  } catch (e) { closePreferenceError.value = e instanceof Error ? e.message : '关闭方式暂时无法读取。' }
  finally { closePreferenceBusy.value = false }
}
async function saveClosePreference(event: Event) {
  const input = event.target as HTMLSelectElement
  const behavior = input.value as CloseBehavior
  if (!desktop || closePreferenceBusy.value || !closePreferenceReady.value || !['ask', 'background', 'quit'].includes(behavior)) { input.value = closeBehavior.value; return }
  closePreferenceBusy.value = true; closePreferenceFeedback.value = ''; closePreferenceError.value = ''
  try {
    const value = await invoke<{ behavior: CloseBehavior }>('native.closePreferences.set', { behavior })
    if (!['ask', 'background', 'quit'].includes(value.behavior)) throw new Error('关闭方式未能保存，请重试。')
    closeBehavior.value = value.behavior; closePreferenceFeedback.value = '关闭方式已保存。'
  } catch (e) { closePreferenceError.value = e instanceof Error ? e.message : '关闭方式未能保存，请重试。' }
  finally { closePreferenceBusy.value = false; input.value = closeBehavior.value }
}
watch(() => props.page, value => { if (value === 'settings') void loadClosePreference() }, { immediate: true })
const logQuery = ref('')
const logLevel = ref('all')
const logs = computed(() => props.snapshot.logs.filter(l => (logLevel.value === 'all' || l.level === logLevel.value) && l.message.toLowerCase().includes(logQuery.value.toLowerCase())).slice().reverse())
watch(() => props.page, () => { query.value = ''; pathError.value = ''; removingId.value = '' })
</script>

<template>
  <section v-if="page === 'setup'" class="secondary-page">
    <header class="page-heading"><p class="eyebrow">开始创作 · 本地环境</p><h1>安装与连接</h1><p class="muted">{{ snapshot.settings.initialized ? '已有环境已识别，可以检查或调整连接。' : '自动准备适合设备的环境，也可以连接已有 ComfyUI。' }}</p></header>
    <div class="panel hardware-strip"><PhCpu :size="30" /><div><strong>{{ gpu }}</strong><p class="muted">{{ vram }} · {{ snapshot.hardware.ramGb > 0 ? `${snapshot.hardware.ramGb.toFixed(0)} GB 内存` : '内存待检测' }}</p></div><span class="badge">{{ snapshot.hardware.driver ? `驱动 ${snapshot.hardware.driver}` : '驱动待检测' }}</span></div>
    <BootstrapSetup :snapshot="snapshot" @complete="emit('action', 'snapshot')" @create="emit('create')" />
    <h2 class="section-heading">连接已有环境</h2>
    <form class="panel path-panel" @submit.prevent="save">
      <div v-for="field in pathFields" :key="field.key" class="path-row"><label :for="`setup-${field.key}`">{{ field.label }}</label><div><input :id="`setup-${field.key}`" v-model="draft[field.key]" class="input" :disabled="busy" spellcheck="false" /><p class="path-hint muted">{{ field.hint }}</p></div><button class="btn secondary" type="button" :disabled="busy" @click="emit('action', 'native.chooseDirectory', { field: field.key })"><PhFolderOpen :size="17" />选择目录</button></div>
      <div class="path-row"><label for="setup-url">服务地址</label><div><input id="setup-url" v-model="draft.engineUrl" class="input" :disabled="busy" spellcheck="false" /><p class="path-hint muted">仅连接本机服务，默认端口 8188</p></div></div>
      <p v-if="pathError" class="error" role="alert">{{ pathError }}</p>
      <div class="form-footer"><p class="muted"><PhInfo :size="17" />已有环境无需重复下载；检查路径后即可连接。</p><button class="btn primary" type="submit" :disabled="busy"><PhCheckCircle :size="18" />{{ busy ? '检查中…' : '保存并检查' }}</button></div>
    </form>
    <div class="panel setup-template"><img src="/forest-preview.webp" alt="雾林晨光，静态模板示例" /><div><h3>{{ snapshot.templates[0]?.name ?? 'MiniMax H3' }}</h3><p class="muted">{{ snapshot.templates[0]?.audio === false ? '图生或文生视频，当前 Lite 方案不含音频。' : '图生或文生视频，原生方案支持同步音轨。' }}</p><small class="muted">封面为设计示例，实际输出取决于你的素材和参数。</small></div><div class="template-stat"><span class="muted">本地资源文件</span><strong>{{ installed }} / {{ snapshot.resources.length }}</strong><small class="muted">文件存在不代表完整性校验通过</small></div></div>
  </section>

  <section v-else-if="page === 'library'" class="secondary-page">
    <header class="page-heading"><p class="eyebrow">模板 · 精选</p><h1>工作流库</h1><p class="muted">少一点配置，多一点创作。</p></header>
    <div class="toolbar"><div class="search-field"><PhMagnifyingGlass :size="21" /><input v-model="query" aria-label="搜索工作流" placeholder="搜索工作流" /><button v-if="query" class="icon-clear" aria-label="清空搜索" @click="query = ''"><PhX :size="17" /></button></div><span class="badge">图生视频</span></div>
    <div class="section-top template-section-heading"><h2>从这里开始</h2><span class="muted small">{{ templates.length }} 个精选模板 · 两种创作方式</span></div>
    <div class="template-grid">
    <article v-for="card in templateCards" :key="`${card.template.id}-${card.mode}`" class="panel library-card"><div class="template-image"><img :src="card.mode === 'image' ? '/coast-inspiration.webp' : '/camera-studio.webp'" :alt="card.mode === 'image' ? '海岸公路创作示意图' : '摄影机与胶片创作示意图'" /><span>创作示意图</span></div><div class="template-copy"><p class="eyebrow">{{ card.mode === 'image' ? '图生视频' : '文生视频' }} · MiniMax H3</p><h2>{{ card.mode === 'image' ? '让一帧画面，继续讲述。' : '从一句灵感，到一个镜头。' }}</h2><span class="readiness" :class="{ good: card.template.ready && engineReady }"><component :is="card.template.ready && engineReady ? PhCheckCircle : PhInfo" :size="18" />{{ engineReady ? (card.template.ready ? '依赖检查通过' : '依赖待处理') : '引擎离线 · 运行条件待检查' }}</span><p class="muted">{{ card.mode === 'image' ? '添加首帧图片，描述接下来的镜头。' : '输入描述，无需首帧图片。' }}</p><details class="template-details"><summary>模板参数与设备</summary><dl class="details"><dt>输入</dt><dd>{{ card.mode === 'image' ? '图片 + 提示词' : '提示词' }}</dd><dt>输出</dt><dd>MP4 · 音轨按运行方案提供</dd><dt>默认时长</dt><dd>{{ (card.template.frames / card.template.fps).toFixed(2) }} 秒 · {{ card.template.fps }} fps</dd><dt>采样步数</dt><dd>{{ card.template.defaultSteps }} 步</dd></dl><p class="muted small">{{ card.template.name }} · {{ gpu }} · {{ vram }}</p></details><div class="actions"><button class="btn primary" @click="emit('create', card.mode)"><PhPlay :size="18" weight="fill" />{{ card.mode === 'image' ? '图片开始创作' : '文字开始创作' }}</button><button class="btn secondary" :disabled="busy" @click="dependencies">查看依赖</button></div></div></article>
    </div>
    <div v-if="!templates.length" class="panel empty-state"><PhMagnifyingGlass :size="36" /><h3>没有匹配的精选模板</h3><p class="muted">试试其他关键词。</p><button class="btn secondary" @click="query = ''">清空搜索</button></div>
    <WorkflowLibrary :snapshot="snapshot" :query="query" :busy="busy" @refresh="emit('action', 'snapshot')" />
    <div v-if="showDependencies" class="panel dependency-panel"><h3>模板依赖</h3><div v-for="item in snapshot.templates" :key="item.id"><p v-if="!engineReady" class="muted">请启动引擎后检查节点与模型。</p><ul><li v-for="model in item.models" :key="model">{{ model }}</li></ul><p v-for="issue in item.issues" :key="issue" class="warning">{{ issue }}</p></div></div>
    <p class="page-note muted">精选模板在创作工作台使用；个人工作流在原生节点编辑器运行。封面为创作示例，运行前请检查环境。</p>
  </section>

  <section v-else-if="page === 'tasks'" class="secondary-page">
    <header class="page-heading"><p class="eyebrow">生成记录 · 本地保存</p><h1>任务与作品</h1><p class="muted">进度清楚，结果随时可找。</p></header>
    <div class="tab-toolbar"><div class="tabs" role="tablist" aria-label="任务与作品"><button :class="{ active: taskTab === 'tasks' }" role="tab" :aria-selected="taskTab === 'tasks'" @click="taskTab = 'tasks'">任务</button><button :class="{ active: taskTab === 'works' }" role="tab" :aria-selected="taskTab === 'works'" @click="taskTab = 'works'; statusFilter = 'all'">作品</button></div><div class="search-field compact"><PhMagnifyingGlass :size="20" /><input v-model="query" aria-label="搜索任务或作品" placeholder="搜索任务或作品" /></div></div>
    <div class="task-layout"><div class="task-list-column">
      <div v-if="currentTask && taskTab === 'tasks'" class="current-task"><h3>当前任务 · {{ currentTask.title }}</h3><p class="readiness good"><PhActivity :size="20" />{{ statusNames[currentTask.status] }}</p><dl class="details"><dt>当前阶段</dt><dd>{{ currentTask.stage || '等待引擎反馈' }}</dd></dl><div class="node-progress"><div><strong>{{ currentTask.progress ? `节点进度 ${percent(currentTask)}%` : '等待节点进度' }}</strong><progress v-if="currentTask.progress" :value="currentTask.progress.value" :max="currentTask.progress.max || 1" /><p class="muted small">仅表示当前节点，不代表整体进度{{ currentTask.progress?.node ? ` · 节点 ${currentTask.progress.node}` : '' }}</p></div><button class="btn secondary" :disabled="busy" @click="emit('action', 'task.cancel', { id: currentTask.id })">取消任务</button></div></div>
      <div class="record-heading"><h3>{{ taskTab === 'works' ? '作品记录' : '任务记录' }}</h3><select v-if="taskTab === 'tasks'" v-model="statusFilter" class="input status-select" aria-label="筛选任务状态"><option value="all">全部状态</option><option value="queued">排队中</option><option value="running">生成中</option><option value="completed">已完成</option><option value="failed">失败</option><option value="interrupted">已中断</option><option value="unknown">状态待确认</option></select></div>
      <div v-if="!visibleTasks.length" class="empty-state"><PhFilmStrip :size="40" /><h3>{{ snapshot.tasks.length ? '没有符合条件的记录' : '第一段视频，从这里开始' }}</h3><p class="muted">{{ snapshot.tasks.length ? '调整搜索词或筛选条件。' : '完成创作后，任务和作品会保存在这里。' }}</p><button class="btn primary" @click="emit('create')">开始创作</button></div>
      <article v-for="task in visibleTasks" :key="task.id" class="task-row" :class="{ selected: selectedTask?.id === task.id }"><button class="task-select" :aria-pressed="selectedTask?.id === task.id" @click="selectedId = task.id"><span class="task-symbol"><PhFilmStrip :size="24" /></span><span><strong :title="task.title">{{ task.title }}</strong><small class="muted">{{ date(task.createdAt) }} · {{ task.params.width }}×{{ task.params.height }}</small></span></button><span class="task-status" :class="{ good: task.status === 'completed', warning: retryable(task) }">{{ statusNames[task.status] }}</span><button v-if="cancellable(task)" class="btn secondary small-button" :disabled="busy" @click="emit('action', 'task.cancel', { id: task.id })">取消</button><button v-else class="btn secondary small-button" @click="selectedId = task.id">查看</button></article>
      <nav v-if="allVisibleTasks.length > pageSize" class="pagination" aria-label="任务记录分页"><span class="muted small">共 {{ allVisibleTasks.length }} 条 · 每页 {{ pageSize }} 条</span><button class="btn secondary" :disabled="pageIndex <= 1" @click="pageIndex--">上一页</button><span class="small">{{ pageIndex }} / {{ pageCount }}</span><button class="btn secondary" :disabled="pageIndex >= pageCount" @click="pageIndex++">下一页</button></nav>
    </div><aside class="preview-column"><h3>作品预览</h3><template v-if="selectedTask"><video v-if="selectedTask.status === 'completed' && selectedTask.outputs.length" :key="selectedTask.id" :src="mediaUrl(selectedTask.outputs[0]!)" controls preload="metadata" aria-label="生成作品预览" /><div v-else class="preview-empty"><PhFilmStrip :size="44" /><p>{{ selectedTask.status === 'completed' ? '该记录暂无可预览的输出文件' : '作品完成后将在这里显示' }}</p></div><h3>{{ selectedTask.title }}</h3><p class="muted">{{ statusNames[selectedTask.status] }} · {{ date(selectedTask.createdAt) }}</p><p class="muted">{{ selectedTask.params.width }}×{{ selectedTask.params.height }} · {{ (selectedTask.params.frames / 24).toFixed(2) }} 秒</p><p v-if="selectedTask.error" class="error task-error" role="alert">{{ selectedTask.error }}</p><div class="actions wrap"><button v-if="selectedTask.status === 'completed' && selectedTask.outputs.length" class="btn primary" :disabled="busy" @click="emit('action', 'native.export', { taskId: selectedTask.id, index: 0 })"><PhExport :size="18" />导出 MP4</button><button class="btn secondary" @click="emit('restore', selectedTask)"><PhSlidersHorizontal :size="18" />回填参数</button><button v-if="retryable(selectedTask)" class="btn secondary" :disabled="busy" @click="emit('action', 'task.retry', { id: selectedTask.id })"><PhArrowClockwise :size="18" />重新生成</button></div><div v-if="removable(selectedTask)" class="history-delete"><template v-if="removingId === selectedTask.id"><p role="status">删除这条历史记录？此操作无法撤销，视频和素材文件会保留。</p><div class="actions wrap"><button ref="keepButton" class="btn secondary" :disabled="busy" @click="keepHistory">保留记录</button><button class="btn secondary delete-confirm" :disabled="busy" @click="removeHistory(selectedTask)"><PhTrash :size="18" />确认删除记录</button></div></template><button v-else ref="deleteButton" class="text-action" :disabled="busy" @click="requestRemove(selectedTask)"><PhTrash :size="18" />删除历史记录</button></div><p v-else class="muted small">任务结束后可删除记录；状态待确认的任务需先确认运行状态。</p><p v-if="retryable(selectedTask)" class="muted small">重新生成会创建新的任务并再次运行；不会续接失败节点。</p><details class="params-details"><summary>查看生成参数</summary><p>{{ selectedTask.params.prompt }}</p><p class="muted small">种子 {{ selectedTask.params.seed }} · {{ selectedTask.params.steps }} 步 · {{ selectedTask.params.frames }} 帧</p></details></template><div v-else class="preview-empty"><PhFilmStrip :size="44" /><p>选择一条记录，查看作品与参数</p></div><p class="page-note muted small">保留种子与生成参数，方便继续创作。</p></aside></div>
  </section>

  <section v-else-if="page === 'resources'" class="secondary-page">
    <header class="page-heading heading-with-action"><div><p class="eyebrow">模型 · 节点 · 环境</p><h1>资源中心</h1><p class="muted">找到适合设备的视频模型，按教程开始本地创作。</p></div><button class="btn primary" :disabled="busy" @click="emit('action', 'resource.scan')"><PhArrowClockwise :size="18" />检查本地资源</button></header>
    <div class="tabs resource-mode-tabs" role="tablist" aria-label="资源中心内容"><button role="tab" :aria-selected="resourceMode === 'recommendations'" :class="{ active: resourceMode === 'recommendations' }" @click="resourceMode = 'recommendations'">模型推荐与教程</button><button role="tab" :aria-selected="resourceMode === 'local'" :class="{ active: resourceMode === 'local' }" @click="resourceMode = 'local'">本地资源</button></div><ModelRecommendations v-if="resourceMode === 'recommendations'" :snapshot="snapshot" @action="(command, payload) => emit('action', command, payload)" @create="emit('create')" /><div v-else class="resource-layout"><div class="panel resource-main"><div class="section-top"><h3>MiniMax H3 · 图生视频</h3><span class="muted small">本地文件检查</span></div><div class="tabs" role="tablist" aria-label="资源类型"><button v-for="tab in [{ key: 'model', label: '模型' }, { key: 'node', label: '节点' }, { key: 'environment', label: '环境' }]" :key="tab.key" role="tab" :aria-selected="resourceTab === tab.key" :class="{ active: resourceTab === tab.key }" @click="resourceTab = tab.key">{{ tab.label }}</button></div><div class="resource-table"><div class="resource-table-head"><span>资源 / 本地路径</span><span>大小</span><span>状态</span></div><article v-for="resource in resources" :key="resource.id" class="resource-row"><div><strong>{{ resource.name }}</strong><p class="muted small resource-path" :title="resource.path">{{ resource.path }}</p></div><span>{{ size(resource.sizeBytes) }}</span><span class="resource-state" :class="resource.status === 'installed' ? 'good' : 'warning'"><component :is="resource.status === 'installed' ? PhCheckCircle : PhWarningCircle" :size="16" />{{ resource.status === 'installed' ? '文件存在' : '缺失' }}</span></article><div v-if="!resources.length" class="empty-state"><PhInfo :size="28" /><p class="muted">暂无该类资源检查结果</p></div></div><p class="page-note muted small">文件存在后，点击“检查模板依赖”确认节点与模型名称是否匹配。</p></div><aside class="panel resource-side"><PhFolderOpen :size="30" /><h3>复用已有模型</h3><